// POST /foto-conta/turmas/:turmaId/homologar
export const HomologarPacoteCorpoSchema = z.object({
  cenario: z.string().min(3).max(50),
  dadosPacote: z.object({
    temaGerado: z.string().max(60),
    foto1Url: z.string().url(),
    foto2Url: z.string().url(),
    detalhesPersistentes: z.array(z.object({
      id: z.string(),
      nome: z.string(),
      coordenadasFoto1: z.object({ x: z.number(), y: z.number(), raio: z.number() }),
      coordenadasFoto2: z.object({ x: z.number(), y: z.number(), raio: z.number() })
    })).min(3).max(4),
    paresGrid: z.array(z.object({
      parId: z.string(),
      fotoAId: z.string(),
      fotoBId: z.string(),
      fotoAUrl: z.string().url(),
      fotoBUrl: z.string().url()
    })).length(3)
  })
});

edicoes.para:
// Contrato de Saída de IA e Homologação de Pacote
export const DetalheInvarianteSchema = z.object({
  id: z.string().min(1).max(50),
  nome: z.string().min(2).max(60),
  coordenadasFoto1: z.object({
    x: z.number().min(0).max(100),
    y: z.number().min(0).max(100),
    raio: z.number().min(5).max(30)
  }),
  coordenadasFoto2: z.object({
    x: z.number().min(0).max(100),
    y: z.number().min(0).max(100),
    raio: z.number().min(5).max(30)
  })
});

export const ParGridItemSchema = z.object({
  parId: z.string().min(1).max(50),
  fotoAId: z.string().min(1).max(50),
  fotoBId: z.string().min(1).max(50),
  fotoAUrl: z.string().url(),
  fotoBUrl: z.string().url(),
  detalheCompartilhado: z.string().min(2).max(60)
});

export const PacoteMisterioSchema = z.object({
  temaGerado: z.string().min(3).max(60),
  cenario: z.string().min(3).max(50),
  foto1Url: z.string().url(),
  foto2Url: z.string().url(),
  detalhesPersistentes: z.array(DetalheInvarianteSchema).min(3).max(4),
  paresGrid: z.array(ParGridItemSchema).length(3)
});
export type PacoteMisterio = z.infer<typeof PacoteMisterioSchema>;

// POST /foto-conta/turmas/:turmaId/homologar
export const HomologarPacoteCorpoSchema = z.object({
  cenario: z.string().min(3).max(50),
  dadosPacote: PacoteMisterioSchema
});

juiz_evidencia_saida:
A linha em C1 explicita que a validação é processada exclusivamente no servidor com gabarito exclusivo no backend para impedir trapaça no cliente, citando o conceito justamente para vedar o gabarito no navegador/bundle.

```json
{
  "agente": "juiz-de-achados",
  "status": "aprovado",
  "decisoes": [
    {
      "id": "C1",
      "veredito": "cita_para_descartar",
      "citacoes": [
        "- **Garante:** Toda validação da ordenação algorítmica de passos é processada exclusivamente no servidor (gabarito exclusivo no backend, impedindo trapaça via devtools no cliente). A regra ternária de EF01CO03 mede estritamente a 1ª tentativa do aluno. As tentativas seguintes são de valor pedagógico/aprendizagem, sem limite de repetição até acerto ou gate final docente. O dashboard do professor exibe tentativas e status (acertou / ainda tentando). Ao finalizar, a tela exibe a insígnia de \"Detetive da Foto\"."
      ]
    }
  ]
}
```

