        'E5': `
          <p><strong>8 e 9. O estudante forma pares de fotos e organiza os passos do detetive:</strong></p>
          <p>O estudante vê na tela um mural com seis fotos menores de outros cantos da escola (horta, biblioteca, quadra), unindo fotos que compartilham o mesmo detalhe no fundo. Depois, organiza três cartões na ordem das ações do detetive (olhar de perto 🔍, pensar 🤔, decidir ✅).</p>
          <p>A medição para EF01CO03 ocorre estritamente na 1ª tentativa; as seguintes são pedagógicas livres. Ao terminar, a tela exibe a insígnia conquistada "Detetive da Foto" e descansa em repouso passivo.</p>
        `
      };

      const nomesEtapas = {
        'E0': 'E0 · Preparo Docente no Hub',
        'E1': 'E1 · Desafiar (Abertura do Álbum)',
        'E2': 'E2 · Navegar (Investigação com Lupa)',
        'E3': 'E3 · Decidir (Aposta com Cadeado)',
        'E4': 'E4 · Resultado / Aha (Morphing e Recap)',
        'E5': 'E5 · Explicar (Grid, Passos e Insígnia)'
      };

      // Monta o trilho esquerdo agrupado por etapa
      const trilho = document.getElementById('trilhoNavegacao');
      let etapaAtualNoTrilho = '';
      let conteinerGrupo = null;

      quadros.forEach((quadro, idx) => {
        const etapa = quadro.dataset.etapa;
        const screenId = quadro.dataset.screenId;
        const estado = quadro.dataset.estado;

        if (etapa !== etapaAtualNoTrilho) {
          etapaAtualNoTrilho = etapa;
          conteinerGrupo = document.createElement('div');
          conteinerGrupo.className = 'trilho-grupo-etapa';

          const rotuloEtapa = document.createElement('div');
          rotuloEtapa.className = 'trilho-etapa-rotulo';
          rotuloEtapa.textContent = nomesEtapas[etapa] || etapa;
          conteinerGrupo.appendChild(rotuloEtapa);
          trilho.appendChild(conteinerGrupo);
        }

        const item = document.createElement('div');
        item.className = 'trilho-item' + (idx === 0 ? ' ativo' : '');
        item.id = 'trilho-item-' + idx;
        item.setAttribute('role', 'button');
        item.setAttribute('tabindex', '0');

        const spanId = document.createElement('span');
        spanId.className = 'trilho-item-id';
        spanId.textContent = screenId;

        const spanEstado = document.createElement('span');
        spanEstado.className = 'trilho-item-estado';
        spanEstado.textContent = estado;

        item.appendChild(spanId);
        item.appendChild(spanEstado);

        item.addEventListener('click', () => navegarPara(idx));
        item.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            navegarPara(idx);
          }
        });

        conteinerGrupo.appendChild(item);
      });

      // Função de atualização da tela
      function navegarPara(indice) {
        if (indice < 0 || indice >= quadros.length) return;

        // Desativa quadro anterior
        quadros[indiceAtual].classList.remove('tela-ativa');
        const itemAntigo = document.getElementById('trilho-item-' + indiceAtual);
        if (itemAntigo) itemAntigo.classList.remove('ativo');

        // Ativa novo quadro
        indiceAtual = indice;
        const qAtivo = quadros[indiceAtual];
        qAtivo.classList.add('tela-ativa');

        const itemNovo = document.getElementById('trilho-item-' + indiceAtual);
        if (itemNovo) {
          itemNovo.classList.add('ativo');
          itemNovo.scrollIntoView({ block: 'nearest' });
        }

        // Atualiza barra superior
        const etapa = qAtivo.dataset.etapa;
        const screenId = qAtivo.dataset.screenId;
        const estado = qAtivo.dataset.estado;

        document.getElementById('topoEtapa').textContent = (nomesEtapas[etapa] || etapa) + ' · ' + screenId;
        document.getElementById('contadorTelas').textContent = 
          String(indiceAtual + 1).padStart(2, '0') + ' / ' + String(quadros.length).padStart(2, '0');

        // Marcas visuais (PICO, AHA, MEMORÁVEL)
        const badgeMarca = document.getElementById('topoMarca');
        if (screenId === 'E3-ALU-01') {
          badgeMarca.textContent = 'PICO';
          badgeMarca.className = 'badge-marca badge-pico';
          badgeMarca.style.display = 'inline-block';
        } else if (screenId === 'E4-ALU-01') {
          badgeMarca.textContent = 'AHA';
          badgeMarca.className = 'badge-marca badge-aha';
          badgeMarca.style.display = 'inline-block';
        } else if (screenId === 'E4-ALU-02') {
          badgeMarca.textContent = 'MEMORÁVEL';
          badgeMarca.className = 'badge-marca badge-mem';
          badgeMarca.style.display = 'inline-block';
        } else {
          badgeMarca.style.display = 'none';
        }

        // Atualiza painel lateral
        document.getElementById('painelEtiqueta').textContent = 'Etapa ' + etapa;
        document.getElementById('painelNome').textContent = qAtivo.dataset.titulo || screenId;
        document.getElementById('painelTexto').innerHTML = textosPorEtapa[etapa] || '<p>Informação pedagógica em processo.</p>';

        // Exibe aviso de concessão demo nas telas de congelamento
        const painelConcessao = document.getElementById('painelConcessao');
        if (screenId === 'E3-ALU-02' || screenId === 'E5-ALU-03') {
          painelConcessao.style.display = 'block';
        } else {
          painelConcessao.style.display = 'none';
        }

        // Atualiza rodapé
        document.getElementById('rodapeTelaId').textContent = screenId + ' (' + estado + ')';
        document.getElementById('rodapeAcao').textContent = qAtivo.dataset.acao || '—';
        document.getElementById('rodapeDepois').textContent = qAtivo.dataset.depois || '—';

        // Atualiza botões
        document.getElementById('btnAnterior').disabled = (indiceAtual === 0);
        document.getElementById('btnProximo').disabled = (indiceAtual === quadros.length - 1);
      }

      // Eventos de clique nos botões
      document.getElementById('btnAnterior').addEventListener('click', () => navegarPara(indiceAtual - 1));
      document.getElementById('btnProximo').addEventListener('click', () => navegarPara(indiceAtual + 1));

      // Atalhos de teclado (Setas esquerda e direita)
      window.addEventListener('keydown', (e) => {
        if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
        if (e.key === 'ArrowRight' || e.key === 'PageDown') {
          e.preventDefault();
          navegarPara(indiceAtual + 1);
        } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
          e.preventDefault();
          navegarPara(indiceAtual - 1);
        } else if (e.key === 'Home') {
          e.preventDefault();
          navegarPara(0);
        } else if (e.key === 'End') {
          e.preventDefault();
          navegarPara(quadros.length - 1);
        }
      });

      // Inicializa na tela 0
      navegarPara(0);
    })();
  </script>
